using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class LandmarkFenceAudit{static LandmarkFenceAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("LandmarkFenceAudit.request"))return;File.Delete("LandmarkFenceAudit.request");var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var rs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy);File.WriteAllLines("FinalEnvironmentRoadReview/LandmarkFenceAudit.txt",rs.Where(r=>r.bounds.size.y>8&&r.bounds.size.y<65&&r.bounds.size.x>35&&r.bounds.size.z>30&&r.bounds.min.y<29).Select(r=>r.name+" | "+(r.sharedMaterial?r.sharedMaterial.name:"")+" | "+r.bounds));var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);foreach(var r in rs.Where(r=>r.name.StartsWith("Building_06_02_1_0")||(r.sharedMaterial&&r.sharedMaterial.name=="Bus Station"&&r.bounds.size.y>8))){var c=r.bounds.center;foreach(float sign in new[]{-1f,1f})cap.Invoke(null,new object[]{sc,new Vector3(c.x+sign*85,65,c.z+15),new Vector3(c.x,34,c.z),"Fence-Audit-"+r.name.Replace(" ","-")+"-"+sign});}}}